-- Import of Driver's Trip Ticket.xlsx, Trips worksheet.
-- 1695 source rows; IDs are stable by source worksheet row so rerunning safely updates imported rows.
-- Blank source values remain blank; N/A odometer markers are stored as NULL.
-- Odometer values and source-order anomalies are preserved unchanged.
begin;

create table if not exists public.driver_trip_tickets (
  id text primary key,
  trip_date date not null,
  dtt_no text not null,
  vehicle text not null,
  driver_name text not null,
  leaving_from text not null,
  going_to text not null,
  odo_start numeric(12, 2),
  odo_finish numeric(12, 2),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.driver_trip_tickets
  alter column odo_start type numeric(12, 2) using odo_start::numeric,
  alter column odo_finish type numeric(12, 2) using odo_finish::numeric;
alter table public.driver_trip_tickets drop constraint if exists driver_trip_tickets_odometer_range;

on conflict (id) do update set
  trip_date = excluded.trip_date,
  dtt_no = excluded.dtt_no,
  vehicle = excluded.vehicle,
  driver_name = excluded.driver_name,
  leaving_from = excluded.leaving_from,
  going_to = excluded.going_to,
  odo_start = excluded.odo_start,
  odo_finish = excluded.odo_finish,
  updated_at = now();
