-- Keep this check for new/updated rows while allowing source-workbook odometer anomalies.
alter table public.driver_trip_tickets
  add constraint driver_trip_tickets_odometer_range
  check (odo_finish is null or odo_start is null or odo_finish >= odo_start) not valid;

create index if not exists driver_trip_tickets_trip_date_idx
  on public.driver_trip_tickets (trip_date desc);
create index if not exists driver_trip_tickets_dtt_no_idx
  on public.driver_trip_tickets (dtt_no);
alter table public.driver_trip_tickets enable row level security;
drop policy if exists "Allow all for driver_trip_tickets" on public.driver_trip_tickets;
create policy "Allow all for driver_trip_tickets"
  on public.driver_trip_tickets for all using (true) with check (true);
grant select, insert, update, delete on public.driver_trip_tickets to anon, authenticated;

commit;
